dslRule:
/*!
@id: eclipse.dialogs.use-idialogconstants-cancel-label
@description: Replace specific JavaHoverMessages constant for cancel button with IDialogConstants.CANCEL_LABEL.
@severity: INFO
*/
org.eclipse.jdt.internal.ui.text.java.hover.JavaHoverMessages.ProblemHover_chooseSettingsTypeDialog_button_cancel
=>
org.eclipse.jface.dialogs.IDialogConstants.CANCEL_LABEL
;;

beforeExample:
import org.eclipse.jface.dialogs.MessageDialog;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.jdt.internal.ui.text.java.hover.JavaHoverMessages;

public class MyDialog extends MessageDialog {
    public MyDialog(Shell parentShell, String dialogTitle, String dialogMessage, int dialogImageType, String[] dialogButtonLabels, int defaultIndex) {
        super(parentShell, dialogTitle, null, dialogMessage, dialogImageType, dialogButtonLabels, defaultIndex);
    }
    public static void open(Shell shell) {
        String[] buttons= new String[] {
            "Button1",
            "Button2",
            JavaHoverMessages.ProblemHover_chooseSettingsTypeDialog_button_cancel
        };
        new MyDialog(shell, "Title", "Message", QUESTION, buttons, 0).open();
    }
}

afterExample:
